CREATE OR REPLACE FUNCTION public.protect_creator_sample_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.creator_samples WHERE creator_id=OLD.id) THEN RAISE EXCEPTION 'Creator has sent samples; edit details instead of deleting'; END IF; RETURN OLD; END $$; CREATE TRIGGER protect_creator_sample_history BEFORE DELETE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.protect_creator_sample_history();